9	/** Where each session's own writes land, on disk so another session — another process, another window — can look them up: nothing here assumes they share memory. */
10	const dirFor = (workspaceRoot: string): string => join(workspaceRoot, '.agent', 'sessions')
11	
12	/**
13	 * Attributes a file's content to the KiwiAgent session that last wrote it, so
14	 * a stale-write refusal can name who: this session's own writes go in here,
15	 * another session's are read back off disk. A thin attribution log, not the
16	 * fuller claim registry (deadlines, heartbeats, denying a live session's
17	 * hold) `docs/features/coordination.md#Claims` describes — nothing this
18	 * feature's rules ask for yet needs those.
19	 */
20	export class FileHands {
21	  constructor(
22	    private readonly workspaceRoot: string,
23	    private readonly sessionId: string,
24	    private readonly mode: SessionMode,
25	    private readonly feature: string | undefined,
26	  ) {}
27	
28	  /** Records that this session's own write left `path` at `mtimeMs`. */
29	  async recordWrite(path: string, mtimeMs: number): Promise<void> {
30	    const dir = dirFor(this.workspaceRoot)
31	    const file = join(dir, `${this.sessionId}.json`)
32	    const registry: Registry = (await readRegistry(file)) ?? {
33	      id: this.sessionId,
34	      mode: this.mode,
35	      ...(this.feature !== undefined ? { feature: this.feature } : {}),
36	      files: {},
37	    }
38	    registry.files[path] = mtimeMs
39	    await mkdir(dir, { recursive: true })
40	    await writeFile(file, JSON.stringify(registry), 'utf8').catch(() => undefined)
41	  }
42	
43	  /** The other KiwiAgent session whose own write left `path` at exactly `mtimeMs`, if one did. */
44	  async whoWrote(path: string, mtimeMs: number): Promise<Hand | undefined> {
45	    return this.find(path, mtimeMs, `${this.sessionId}.json`)
46	  }
47	
48	  /** The KiwiAgent session whose own write left `path` at exactly `mtimeMs`, this session's own included, if one did. */
49	  async handFor(path: string, mtimeMs: number): Promise<Hand | undefined> {
50	    return this.find(path, mtimeMs)
51	  }
52	
53	  private async find(path: string, mtimeMs: number, skip?: string): Promise<Hand | undefined> {
54	    let names: string[]
55	    try {
56	      names = await readdir(dirFor(this.workspaceRoot))
57	    } catch {
58	      return undefined
59	    }
60	    for (const name of names) {
61	      if (name === skip) continue
62	      const registry = await readRegistry(join(dirFor(this.workspaceRoot), name))
63	      if (registry && registry.files[path] === mtimeMs) {
64	        return { sessionId: registry.id, mode: registry.mode, ...(registry.feature !== undefined ? { feature: registry.feature } : {}) }
65	      }
66	    }
67	    return undefined
68	  }
69	}
70	
71	async function readRegistry(file: string): Promise<Registry | undefined> {
72	  try {
73	    return JSON.parse(await readFile(file, 'utf8')) as Registry
74	  } catch {
75	    return undefined
76	  }
77	}
78	
79	/**
80	 * What a refusal or notice says about where a change came from: the other
81	 * KiwiAgent session and the feature it works on when the registry names one,
82	 * outside KiwiAgent otherwise — never which tool made the change.
83	 */
84	export function describeHand(hand: Hand | undefined): string {
85	  if (!hand) return 'It was changed from outside KiwiAgent.'
86	  const who = hand.feature ? `a KiwiAgent ${hand.mode} session on "${hand.feature}"` : `a KiwiAgent ${hand.mode} session`
87	  return `It was changed by ${who}.`
