/** The KiwiAgent session whose own write left `path` at exactly `mtimeMs`, this session's own included, if one did. */
async handFor(path: string, mtimeMs: number): Promise<Hand | undefined> {
  return this.find(path, mtimeMs)
}

/**
 * The newest content a session of `feature` is on record as having written
 * to `path`, across every one of its sessions, this one included; undefined
 * when no session of that feature ever recorded a write there with text
 * kept. What verification's foreign-failure narrowing calls "this feature's
 * implementation" of the file, to diff the current content against.
 */
async ownSnapshot(feature: string, path: string): Promise<Snapshot | undefined> {
  let names: string[]
  try {
    names = await readdir(dirFor(this.workspaceRoot))
  } catch {
    return undefined
  }
  let best: Snapshot | undefined
  for (const name of names) {
    const registry = await readRegistry(join(dirFor(this.workspaceRoot), name))
    if (!registry || registry.feature !== feature) continue
    const mtimeMs = registry.files[path]
    const text = registry.texts?.[path]
    if (mtimeMs === undefined || text === undefined) continue
    if (!best || mtimeMs > best.mtimeMs) best = { mtimeMs, text }
  }
  return best
}

