99	      if (name === skip) continue
100	      const registry = await readRegistry(join(dirFor(this.workspaceRoot), name))
101	      if (registry && registry.files[path] === mtimeMs) {
102	        return { sessionId: registry.id, mode: registry.mode, ...(registry.feature !== undefined ? { feature: registry.feature } : {}) }
103	      }
104	    }
105	    return undefined
