  })

  const foreign: Attribute = async () => ({ foreign: true, files: ['src/app/orders.ts'], hand: 'It was changed by a KiwiAgent plan session on "Other feature".' })
  const ours: Attribute = async () => ({ foreign: false, files: ['src/app/orders.ts'] })

